package com.example.inventory.models;
public class Vendor{private int id;private String name,contactInfo;public Vendor(){}public Vendor(int id,String name,String contactInfo){this.id=id;this.name=name;this.contactInfo=contactInfo;}public int getId(){return id;}public void setId(int v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getContactInfo(){return contactInfo;}public void setContactInfo(String v){contactInfo=v;}public String toString(){return id+" - "+name+" ("+contactInfo+")";}}